// EN translation FIRST PASS. Literary editorial approval outstanding.
const OUTCOMES_EN_E291_E360 = Object.freeze({"E291.1":{"s":"The king goes against Arr and forces the lion to accept the outcome of the duel. The baron pays in gold for the unexpectedly saved fort.","f":"Arr knocks the King to the ground and gravely wounds him. The baron turns his face away from the field.","v":{"nf":"The duel is interrupted without the King being gravely wounded, but the dispute over the fort remains open."}},"E291.2":{"s":"You return your own words to the baron, and he is forced to personally come to an agreement with Arr. The baron pays in gold for his release from the royal duel.","f":"The Baron declares your demand treason against the human side and withdraws the guards. A skirmish begins."},"E291.3":{"s":"You pay for the day of truce for both rulers. Arr sits down at the border, and for the first time that morning the baron unfolds the map instead of the sword."},"E291.4":{"s":"You refuse to represent the baron in someone else's fight. Arr turns to the one he actually called."},"E292.1":{"s":"You buy supplies from Pip, and Roach receives another cake for the transaction. The goblin immediately offers a paid dragon smile."},"E292.2":{"s":"You persuade Roach to let travellers pass without buying anything, and Pip refunds some of the gold taken unfairly.","f":"The dragon mistakes the demand for an attempt to deprive him of the cakes and calls the kiosk guards. A skirmish begins."},"E292.3":{"s":"{{heroName}} engages Roach in conversation about his favorite cakes, and customers manage to get in for free. Pip is paid off with gold to stop the flow of complaints.","f":"Roach turns sharply towards the distraction, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The dragon stops the diversion, but none of the eligible fighters are gravely wounded. The kiosk continues to demand purchase."}},"E292.4":{"s":"You go around the kiosk on the other side of the road. Roach follows the party with his eyes, and Pip is already posting the price for the detour."},"E293.1":{"s":"Edran agrees to shelter K-12 for a while and sets him a simple task at the forge. The grateful automaton finds supplies for your party.","f":"The blacksmith is not ready to call the owner of a golem that is two centuries older than him. K-12 remains to wait for the order."},"E293.2":{"s":"You disable K-12 without damaging the workshop and take valuable parts for gold.","f":"The golem declares the shutdown an attack on the owner and raises its metal arms. A skirmish begins."},"E293.3":{"s":"{{heroName}} finds an old note bearing Edran's name and a hidden cache of gold behind the panel. The blacksmith finally gains part of an answer.","f":"The plate closes on the instruments, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The plate protects the mechanism's memory, but no eligible combatants are gravely wounded. The recording remains a mystery."}},"E293.4":{"s":"You walk past the blacksmith shop and don't give orders to K-12. Every few steps the same “What’s the order?” is heard."},"E294.1":{"s":"You allow the skeletons to remain at the fair with already purchased tickets. Grateful pie merchants supply the party with supplies.","f":"The headman does not dare to change the rule about signs of life and leaves the undead in front of the gate. The fair continues to argue."},"E294.2":{"s":"You return the price of the tickets to the skeletons from your treasury. One visitor reluctantly gives up his spoon and goes to the exit."},"E294.3":{"s":"{{heroName}} finds in the charter a definition of a guest as the holder of a valid ticket, which does not specify the condition of the bones. The headman pays in gold and supplies.","f":"{{heroName}} finds two conflicting articles about guests and dead people. The decision has to be postponed until the next fair."},"E294.4":{"s":"You leave the fair where skeletons are trying to buy pies and merchants are trying to sell them hats. The headman is still looking for the correct form."},"E295.1":{"s":"You secure permission to cut down the infested tree, and the dwarves finally take up their axes. Sin thanks you for preventing the disease and gives you supplies.","f":"Neighboring keepers refuse to acknowledge the threat without evidence. The cutting has to be stopped."},"E295.2":{"s":"You leave Sin and the dwarves in front of the diseased tree. No one has yet decided to be the first to put the ax on the trunk."},"E295.3":{"s":"{{heroName}} shows everyone signs of disease on the bark and roots, after which Sin gains the right to stop the infection. The party is rewarded with gold and supplies.","f":"{{heroName}} finds evidence of two similar diseases, but cannot determine whether one is threatening neighboring trees. Felling is postponed."},"E295.4":{"s":"You pay the dwarves to work on behalf of the King, and they remove the infested tree in front of witnesses. Sin supplies the party with supplies."},"E296.1":{"s":"You hold the light circle until dawn, and the pursuers leave without Saar. Elion donates supplies for keeping the oath.","f":"The demons break through the ring of light before the sun rises. The battle begins."},"E296.2":{"s":"You take gold from the pursuers and step outside the circle of light. Elion remains alone to defend the unarmed Saar."},"E296.3":{"s":"You give your pursuers the gold, and they retreat before dawn. Elion does not lower the light border until the last demon disappears."},"E296.4":{"s":"You leave the angel to hold the refuge with your oath. Saar remains silent as the shadows of his pursuers lengthen around the circle."},"E297.1":{"s":"You help the village strengthen the dam near the river, and the residents thank you for the preparations with supplies.","f":"The dam does not have time to rise to the required height, and supplies are wasted on unnecessary work. Oren still promises flooding."},"E297.2":{"s":"You help stockpile water in case of drought, and the villagers pay in gold for their forethought.","f":"Tilly cannot indicate where to look for water underground. Preparation brings no reward."},"E297.3":{"s":"{{heroName}} finds out that both prophets are talking about different hours of tomorrow. The village is preparing for both water and dry land, issuing gold and supplies.","f":"{{heroName}} cannot determine when exactly the prophetic “tomorrow” will begin. The village remains between the dam and the well."},"E297.4":{"s":"You leave Oren with the clouds and Tilly with the cracks in the east. The village makes two plans for one day."},"E298.1":{"s":"You take the black goat from the sight of three armies and return it to the shepherd. He thanks you for the averted battle and gives you supplies.","f":"One of the commanders declares the removal of the goat a violation of the sacred sign. A skirmish begins."},"E298.2":{"s":"The Goat approaches the King, and the armies take this as a sign to stop the rivalry. The leaders pay gold for unexpected mediation.","f":"All three armies see the goat's approach to the King as a common challenge. Instead of a truce, a battle begins."},"E298.3":{"s":"You pay the shepherd for a goat and take him away from the plain before the generals find a new reason for the sign. The animal calmly chews grass."},"E298.4":{"s":"You use up supplies to go around three armies and one goat. The commanders continue to wait to see who he will pay attention to."},"E299.1":{"s":"You sell torn straps, empty boxes and old shoelaces to traders. On Buyer's Day they actually give gold for this.","f":"The traders finally realize that they are buying junk and don't bid anymore. The sale is cancelled."},"E299.2":{"s":"You buy supplies from tired merchants that they are ready to sell at the regular price. The holiday had clearly gone on for them."},"E299.3":{"s":"{{heroName}} finds a buyer who is willing to offer the most for a broken camping spoon. The party receives gold.","f":"{{heroName}} is late: the most desperate merchant has already spent his last coins. There is no good deal."},"E299.4":{"s":"You leave a market where everyone wants to buy other people's unnecessary things. Behind them, two merchants are arguing about a bent fork."},"E300.1":{"s":"You find a cache of gold near a broken cart and see that the traces of all four witnesses really converge here.","f":"At the site of the missing caravan, you are met by armed men hiding among the trees. The battle begins."},"E300.2":{"s":"You pay four travelers for their stories and receive the supplies they saved after the night. The stories remain inconsistent."},"E300.3":{"s":"{{heroName}} compares the four versions and finds where each describes a different part of the attack. At the cart, the party receives gold and supplies.","f":"{{heroName}} discovers that each witness has the correct detail, but the overall course of events cannot be reconstructed. The culprit remains unknown."},"E300.4":{"s":"You leave the four witnesses arguing over the caravan that vanished without a trace. By dawn, even the skeleton has another version."},"E301.1":{"s":"You compel the council to announce that Orlen is alive before the whole city. The captain rewards the correction with gold, and the orchestra hastily changes its tune.","f":"The council refuses to postpone the paid funeral and invites Orlen to wait for it to end. There is no recognition."},"E301.2":{"s":"Orlen decides that a new living person will find something to do in the royal campaign. He joins the party.","f":"The captain does not want to leave the city where a monument has already been erected to him. He refuses to join the party.","v":{"rs":"Orlen agrees to leave with the King, but your party has no room for him. The captain rewards the offer with gold."}},"E301.3":{"s":"{{heroName}} convinces the council to leave the monument as a sign of victory, not Orlen's death. The city pays in gold for the saved budget and a living captain.","f":"{{heroName}} cannot reconcile the council with the obvious fact of Orlen's return. For the protracted proceedings they collect gold."},"E301.4":{"s":"You leave Orlen to argue with his own monument. In the square they are already rehearsing a speech about the untimely death of the captain."},"E302.1":{"s":"You protect Ners while he checks the seals and hands letters to their rightful recipients. The postman rewards you with gold for saving the mail.","f":"One of the impatient men grabs the bag while the others draw their weapons. A skirmish begins."},"E302.2":{"s":"You buy Ners's supplies for the postal route. He asks you not to touch the black envelope."},"E302.3":{"s":"{{heroName}} braces the axle and puts the wheel back in place. Ners rewards the repair with gold and supplies.","f":"While lifting the cart, the jack breaks and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The wheel breaks off during repairs, but none of the eligible fighters are gravely wounded. The postal route has not been resumed."}},"E302.4":{"s":"You leave Ners sorting mail under the gaze of three suspicious recipients. The black seal remains unbroken."},"E303.1":{"s":"Martha herself names the one with whom she wants to go further, and the men finally hear the decision not from the King. The family thanks with supplies for the returned right to choose.","f":"Martha asks to postpone the wedding until both suitors stop arguing, but neither listens. The holiday stops."},"E303.2":{"s":"You convince both men not to turn their return from war into a duel. The priest thanks in gold for the preserved peace.","f":"Both suitors declare themselves insulted and call supporters. A skirmish begins."},"E303.3":{"s":"{{heroName}} refuses to begin the ceremony until Martha gives her free consent. The family pays gold to defend her decision.","f":"{{heroName}} does not receive Martha’s clear consent and postpones the ceremony. The festive procession remains on the road."},"E303.4":{"s":"You move past a wedding where no one thought to ask what the bride wanted. Eld tucks the ceremonial book under his arm."},"E304.1":{"s":"You pay the fine and let Doras knead the dough overnight. By morning, he gives the party fresh bread and supplies."},"E304.2":{"s":"You get an exception for the bakery and the overnight ovens are back in operation. Grateful townspeople share supplies.","f":"The guards demand strict adherence to the decree and do not allow the oven to be opened. The dispute turns into a clash."},"E304.3":{"s":"{{heroName}} organises a silent night shift without clattering baking trays. Doras bakes bread and shares provisions with the party.","f":"One oven still rattles in the night, and the guards confiscate some of the prepared provisions."},"E304.4":{"s":"You leave before the quiet bread riot begins. Outside the gates, the townspeople show very eloquent gestures to the guards."},"E305.1":{"s":"You show customers three incompatible boot sizes, and Fess doesn't have an answer. For stopped deception, the bailiff issues gold.","f":"Fess declares the third boot ceremonial, and customers take his word for it. It is not possible to expose the merchant."},"E305.2":{"s":"You buy supplies from nearby shops while the whole square argues about the size of Asten's legs. Sellers are happy to have at least an ordinary deal."},"E305.3":{"s":"{{heroName}} reveals three seals from different workshops on one “royal” set. Fess returns the gold for the counterfeits.","f":"{{heroName}} cannot refute all the evidence at once, and the merchant charges a fee for the examination. The party loses gold."},"E305.4":{"s":"You allow the market to argue about the three boots of one king. Fess already offers a fourth - “for special occasions.”"},"E306.1":{"s":"You take the recorded confessions of others from the man in the gray cloak and find gold from him for blackmail.","f":"The gray stranger whistles to his assistants, and they rush to save the notes. A skirmish begins."},"E306.2":{"s":"You put an end to the queue, and people stop confessing in the courtyard. Grateful Olm leaves provisions for your party.","f":"The priest does not believe that the walls are betraying other people’s words, and continues the service. The queue remains eavesdropped."},"E306.3":{"s":"{{heroName}} finds enchanted inserts in the walls that amplify whispers. Olm thanks with gold and supplies for the restored secret of confession.","f":"One of the inserts responds with a magical blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The enchanted wall repels explorers, but no eligible combatants are gravely wounded. Confessions can still be heard outside."}},"E306.4":{"s":"You pass by the chapel without stopping at other people's confessions. The man in the gray cloak continues to write quickly."},"E307.1":{"s":"You help the elves complete their farewell to the oak, and keeper Mael shares supplies. Tivan puts away his saw until the ceremony ends.","f":"The elves cannot agree whether the tree should be buried or given a new purpose. The ritual does not end."},"E307.2":{"s":"You convince Tivan not to touch the trunk until Mael resolves the issue with the guardians. The lumberjack pays in gold for the delay achieved.","f":"Tivan is afraid of missing out on the wood for the bridge and refuses to wait. The dispute with the elves continues."},"E307.3":{"s":"{{heroName}} discovers that the oak tree's roots have already died and the wood is suitable for a bridge without harming neighboring trees. Mael thanks with gold and supplies.","f":"An attempt to check the inner rings results in a live root being struck, and {{affectedHeroName}} is severely injured.","v":{"nf":"The remaining roots repel explorers, but no eligible combatants are gravely wounded. The conclusion about oak is not ready."}},"E307.4":{"s":"You do not interfere with the farewell of a nine-hundred-year-old oak tree. Tivan is waiting next to the saw, but does not approach the trunk."},"E308.1":{"s":"You help the hunters herd an invisible deer back into the enclosure and recover stolen food. The party receives supplies.","f":"An invisible beast breaks through the enclosure, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"An invisible deer knocks down the pen, but no eligible combatants are gravely wounded. The dried apples remain with him."}},"E308.2":{"s":"You leave bait for the invisible deer and pay hunters for their supplies. Veira asks to keep the bags tied."},"E308.3":{"s":"{{heroName}} reads footprints in the snow and finds a lair with stolen things and gold. The hunters thank you for the solution.","f":"In a snowy forest, {{affectedHeroName}} is gravely wounded by a sudden blow from an invisible beast.","v":{"nf":"The invisible beast disrupts the pursuit, but none of the eligible fighters are gravely wounded. The tracks break off again."}},"E308.4":{"s":"You leave it to the invisible deer to conquer the hunters and the apples. Veira ties the bags with double knots."},"E309.1":{"s":"At night, the missing note sounds from the forest, and Lior finally dares to answer. There is gold in the old cache near the bridge.","f":"At the sound of music, armed strangers who have nothing to do with the wife’s memory come out of the forest. A skirmish begins."},"E309.2":{"s":"You pay Lior to show you a safe forest path. He sees off the party with a quiet melody without the last sound."},"E309.3":{"s":"{{heroName}} discovers that the answering note comes from an old echo passage behind the bridge. Lior rewards the discovery with gold and supplies.","f":"An attempt to approach the source of the sound ends with a dangerous blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The hidden sound source repels the scouts, but no eligible combatants are gravely wounded. The last note remains a mystery."}},"E309.4":{"s":"You leave Lior on the bridge with an unfinished melody. For the first time that day he doesn't try to finish it."},"E310.1":{"s":"You pay the gardener for the damage caused by the stolen grapes and release the red fox. Elvar records the case as closed without a confession from the defendant."},"E310.2":{"s":"You give away the supplies to replace the seven bunches of grapes, and Rin comes to terms with the loss. He gives gold for a settled dispute."},"E310.3":{"s":"{{heroName}} proves that the fox cannot be convicted of contempt for a fence on the evidence given. The court dismisses the case and rewards you with gold.","f":"{{heroName}} cannot convince Elvar to drop the charge of systematic trespassing. The fox yawns even louder."},"E310.4":{"s":"You leave it to the elven court to decide what the fox thinks about its jurisdiction. The accused calmly licks her other paw."},"E311.1":{"s":"You follow the fireplace and find both guests in a room that was once the kitchen. Evel pays gold for their safe return.","f":"The house rearranges the walls behind it, and {{affectedHeroName}} is gravely wounded when the passage collapses.","v":{"nf":"The rooms close in around the search party, but no eligible combatants are gravely wounded. No guests have been found yet."}},"E311.2":{"s":"You buy provisions from Evel without leaving the doorway. She asks you to let her know if you happen to find her living room."},"E311.3":{"s":"{{heroName}} finds motionless load-bearing walls among the changing rooms and leads guests outside. Evel thanks with gold and supplies.","f":"The ceiling moves before {{heroName}} can secure it, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The ceiling falls, but none of the eligible fighters are gravely wounded. The house does not give up missing guests."}},"E311.4":{"s":"You leave Evel with a house that dislikes its own floor plan. As you go, the doorway behind her turns into a window."},"E312.1":{"s":"You manage to make out the lines of dry leaves, and Teyla uses them to point out the cache of supplies.","f":"The leaves whip up like a whirlwind and inflict {{affectedHeroName}} a serious injury.","v":{"nf":"The whirlwind scatters leaves, but no eligible combatants are gravely wounded. The letter cannot be read."}},"E312.2":{"s":"You give Teyla supplies for the community, and she rewards you with gold. As you part, the roadside leaves stop arranging themselves into words."},"E312.3":{"s":"{{heroName}} marks repeated characters and restores the meaning of the letter. Aras pays in gold for reading the message.","f":"{{heroName}} cannot collect the last line: the leaves scatter with each new gust. The addressee remains unknown."},"E312.4":{"s":"You are not responding to the message that the reader chooses. The last line falls apart as soon as the party leaves."},"E313.1":{"s":"Grum suffers a dignified defeat, keeping his nose intact for his wedding portrait. Haga awards gold for a well-fought duel.","f":"One blow is stronger than intended, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The fight ends in a dangerous clash, but none of the eligible fighters are gravely wounded. Haga does not accept defeat as worthy."}},"E313.2":{"s":"You give the family supplies instead of a duel, and Haga rewards you with gold for sparing the wedding. Grum is still searching for a worthy opponent."},"E313.3":{"s":"{{heroName}} stages an exhibition match in which Grum loses gracefully and keeps his nose intact. Haga rewards the performance with gold.","f":"At a sharp turn, {{affectedHeroName}} is gravely wounded, and the exhibition match has to be interrupted.","v":{"nf":"The exhibition fight is stopped after a dangerous blow, but none of the eligible fighters are gravely wounded. Haga remains dissatisfied."}},"E313.4":{"s":"You wish Grum luck with his wedding and leave Haga to assess the other opponents. The orc promises to try to lose with dignity."},"E314.1":{"s":"You divide the soup between both clans, and at last Burg can ladle it out without fear. The orcs reward the help with provisions.","f":"The leaders demand that they first decide who owns the cauldron, and refuse to even try the soup. Dinner is getting cold."},"E314.2":{"s":"You pay for the copper cauldron and take away the right to control the dinner. Burg is relieved to hand over supplies to end the argument."},"E314.3":{"s":"{{heroName}} finds an old smith's mark beneath the handle, and Burg confirms who commissioned the cauldron. The clans pay gold for resolving the quarrel.","f":"{{heroName}} finds marks from two different craftsmen. The quarrel shifts to the origin of each handle, and the ruling is postponed."},"E314.4":{"s":"You leave while two orc warbands form up over cold soup. Burg promises to stop any battle with his ladle."},"E315.1":{"s":"You remove the catchy border from the banner, and the banner no longer stands out from afar as a target. Urk thanks in gold for the preserved relic.","f":"Mada considers the alteration insufficient and still demands that the banner be burned. The party leaves without reward."},"E315.2":{"s":"You buy provisions from the orc camp without approaching the disputed banner. Urk wonders who will carry it tomorrow."},"E315.3":{"s":"{{heroName}} checks the banner and finds the usual signal paint instead of a curse. Mada gives gold for an explanation.","f":"A protective flash bursts out from the folds of the banner, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The banner flashes dangerously when checked, but no eligible fighters are gravely wounded. The reason has not been revealed."}},"E315.4":{"s":"You leave the orcs with a banner whose visibility has become legendary. Urk moves it even farther from the fire."},"E316.1":{"s":"You catch up with the teenagers at the stream and return the stolen drum to Mog. The clan thanks in gold for the absence of a punitive campaign.","f":"The teenagers call their armed older brothers and refuse to return the instrument. A skirmish begins."},"E316.2":{"s":"You persuade Sara to replace the punitive raid with a music lesson for both clans. Mog rewards you with supplies.","f":"Sar demands exemplary punishment and does not want to hear about children's pranks. The army continues to gather."},"E316.3":{"s":"{{heroName}} intercepts the teenagers at the fork before they can ruin the drum. Sar pays the gold.","f":"During the crossing, {{affectedHeroName}} is gravely wounded when the kidnappers try to escape through a dangerous gorge.","v":{"nf":"The interception fails on a dangerous descent, but none of the eligible fighters is gravely wounded. The drum was not returned."}},"E316.4":{"s":"You leave Sara to listen for the missed fourth beat. Mog covers his face, mortified by the rhythm."},"E317.1":{"s":"You convince Gekh to return to his family, promising to talk about family demands. The clan pays in gold for his release.","f":"Gekh refuses to exchange three meals a day for family debts. Torr doesn’t know whether to rejoice at such a captive."},"E317.2":{"s":"Gekh decides the royal party offers porridge without relatives' complaints. He joins your ranks.","f":"Gekh asks about mealtimes and, on hearing the answer, chooses the cage instead. He will not join you.","v":{"rs":"Gekh agrees to leave the cage, but a new fighter cannot be accepted. Relatives pay the party gold for their attempt."}},"E317.3":{"s":"{{heroName}} negotiates for Gekh to return home without previous debts and with the condition of feeding him on time. The clan thanks with gold.","f":"{{heroName}} cannot reconcile his relatives with Gekh’s demands, and Torr demands payment for the prolonged maintenance. The treasury is losing gold."},"E317.4":{"s":"You leave Gekh enjoying porridge in his cage and Torr wondering how to get rid of such a contented prisoner. The clan is still waiting outside."},"E318.1":{"s":"You withstand one blow from Krach and cross the bridge without striking back. Smith Oba records another custom duly observed.","f":"The club comes down too hard and {{affectedHeroName}} is severely wounded.","v":{"nf":"The blow lands on defense, but none of the eligible fighters are gravely wounded. Failure requires repeating the test."}},"E318.2":{"s":"You pay Krach for the privilege of not being hit and cross the bridge while he stares in surprise at the gold."},"E318.3":{"s":"{{heroName}} takes the blow on a sturdy guard and earns the right to lead the party across. Krach rewards a worthy trial with gold.","f":"The club smashes through the defence, gravely wounding {{affectedHeroName}}.","v":{"nf":"The blow causes no grave wound to an eligible fighter, but Krach declares the trial failed. There is no reward."}},"E318.4":{"s":"You spend supplies reaching another crossing rather than test someone else's club against your head. Oba watches you leave with approval."},"E319.1":{"s":"You find a name in an old cemetery book that matches the skeleton's memories. He thanks in gold for the returned past.","f":"Vess finds several identical records and cannot determine the correct one. The skeleton refuses to be named at random."},"E319.2":{"s":"You give the skeleton supplies for the journey to his former home, and he shares the gold left with him after death."},"E319.3":{"s":"{{heroName}} restores the erased letters on the tombstone, and the skeleton finally reads his own name. Vess thanks with gold.","f":"The old slab responds with a magical blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The tombstone triggers a protective seal, but no eligible combatants are gravely wounded. The name remains forgotten."}},"E319.4":{"s":"You suggest that the skeleton choose a new name instead of waiting for the old records. He studies the blank gravestone thoughtfully."},"E320.1":{"s":"You help the village complete the old funeral words, and the orchestra finally falls silent. Grateful residents give out supplies.","f":"The conductor cannot remember the last verse, and the musicians begin the march again. The ceremony is not over."},"E320.2":{"s":"You pay residents for information about the late owner of the orchestra. Pell listens intently, still conducting."},"E320.3":{"s":"{{heroName}} restores the missing final words of the rite, and the orchestra ends its six-day performance. Pell rewards you with gold and supplies.","f":"The ritual causes a dangerous response of old magic, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"Funeral magic disrupts the execution, but no eligible combatants are gravely wounded. The orchestra continues the march."}},"E320.4":{"s":"You leave the village until the next verse. Pell, having no lungs, still sighs before the new introduction."},"E321.1":{"s":"You acknowledge the literal execution of Walter's will and transfer the house to the children. The deceased thanks in gold for the opportunity to no longer be the owner.","f":"The notary considers Walter's return a legal obstacle and does not formalize the transfer. The family continues to argue for someone else's benefit."},"E321.2":{"s":"You pay for this independent trial, and the notary finally gets time to reread the will. Walter waits patiently."},"E321.3":{"s":"{{heroName}} proves that the condition “after my death” has already occurred once and is not canceled by the resurrection. Walter thanks with gold.","f":"{{heroName}} does not find an indisputable interpretation, and the notary collects a fee. The party loses gold."},"E321.4":{"s":"You leave the children trying to surrender their inheritance to their formerly deceased father. The notary rubs his temples over a perfectly genuine will."},"E322.1":{"s":"You find the seekers behind the inner door and take the golden purse before the tower reaches a hundred.","f":"The score reaches a critical point, and armed guards emerge from the walls. The battle begins."},"E322.2":{"s":"You quickly pick up items left at the doorstep and take supplies without adding any more steps to the tower.","f":"When you try to carry away the bags, armed guards of the counting tower appear in the opening. A skirmish begins."},"E322.3":{"s":"{{heroName}} calculates the shortest path to the abandoned items and retrieves the gold without extra steps.","f":"The walls move abruptly as the route is calculated, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The tower changes passage up to the hundredth step, but none of the eligible fighters is gravely wounded. The cache has not been reached."}},"E322.4":{"s":"You circle the tower without helping it count to a hundred. Behind you, the whisper stops at the next number."},"E323.1":{"s":"You confirm Ark's right to buy the family crown, whether or not he has a head to wear it. The merchant pays gold for the royal clarification.","f":"The merchant refuses to sell jewelry that has nowhere to be worn. Ark demands a written refusal."},"E323.2":{"s":"You buy supplies from a merchant while Ark and the squire discuss shoulder pads. The crown is still on the counter."},"E323.3":{"s":"{{heroName}} suggests displaying the crown on Ark's banner instead of his missing head. The squire is delighted, and the merchant pays gold.","f":"{{heroName}} offers several mounting options, but Ark rejects each as unworthy of the species. The deal is not completed."},"E323.4":{"s":"You do not undertake to judge headless heraldry. Ark demands to bring him the pedigree along with the drawings of the crown."},"E324.1":{"s":"You knock three times on the coffin lid. A satisfied voice from the grave replies, “Still here on the outside.” Rufus discovers a purse of gold beside the gravestone.","f":"After the third blow, armed guards of the grave rise from the ground. A skirmish begins."},"E324.2":{"s":"You pay Rufus to tell you about yesterday's funeral, and he leads the party to the recording of the deceased. The voice from the ground continues to wait for three knocks."},"E324.3":{"s":"{{heroName}} checks the tombstone and finds a ventilation duct through which the voice passes. Rufus thanks you for the peace of mind and gives you supplies.","f":"The ground settles under {{affectedHeroName}}'s feet, causing serious injury.","v":{"nf":"The grave settles dangerously, but none of the eligible combatants are gravely wounded. The source of the voice remains unknown."}},"E324.4":{"s":"You are not answering the voice that wants to check the outside of the lid. Rufus remains near the grave with his hand raised."},"E325.1":{"s":"You pay Chass to navigate the web and receive a tidy receipt. The spider pulls up the broken thread under your feet."},"E325.2":{"s":"You cut the edge of the web and return the old road to the caravan without toll.","f":"The Spider calls for his armed defenders when you cut the bridge he built. A skirmish begins."},"E325.3":{"s":"{{heroName}} finds that the spider web blocks a public road, and no toll was agreed with the road's owners. Chass refunds the gold.","f":"{{heroName}} does not find an accurate record of the right of way, and Chasse charges a fee for resolving the dispute. The party loses gold."},"E325.4":{"s":"You spend supplies to go around the canyon without paying for the spider bridge. Chasse is already writing out a receipt for the next caravan."},"E326.1":{"s":"You confirm Virra's claim: one witness and twelve - different order conditions. The guild returns the gold for the dispute.","f":"The customer calls his bodyguards, considering the decision a violation of the contract. A skirmish begins."},"E326.2":{"s":"You pay the secretary for safe passage through the guild lands. The goose sees off the party with an extremely unfriendly hiss."},"E326.3":{"s":"{{heroName}} discovers that the contract does not specify the number of witnesses and does not define the rights of the goose at all. The guild pays gold for legal clarity.","f":"{{heroName}} cannot prove that the goose was a witness, and the secretary collects legal costs. The party loses gold."},"E326.4":{"s":"You leave before the thirteenth witness appears, while Virra argues with the customer. Goose takes her place at the table."},"E327.1":{"s":"On the balcony you find a gold purse in the pocket of someone else's gloves. Narva assures that she never bought the chairs.","f":"The balcony moves to a nearby window during inspection, and {{affectedHeroName}} is severely injured.","v":{"nf":"The balcony suddenly moves, but none of the eligible fighters are gravely wounded. Other people's things stay upstairs."}},"E327.2":{"s":"You buy travel supplies from Narva and leave without touching the strange balcony. Seliss is already preparing new plans for the house."},"E327.3":{"s":"{{heroName}} discovers that the balcony's supports lead into the old stonework of the neighbouring building, not this wall. Narva rewards the discovery with gold.","f":"One of the balcony's hidden supports breaks and {{affectedHeroName}} is severely injured.","v":{"nf":"The support collapses, but none of the eligible fighters are gravely wounded. The reason for the appearance of the balcony has not been found."}},"E327.4":{"s":"You leave Narva at the balcony without a door. There are already new gloves on the chair, although no one has gone upstairs."},"E328.1":{"s":"You persuade Ilzara to accept the remaining gold and let Taren go without any family intrigue. Her son rewards his freedom with gold.","f":"Ilzara considers simply giving away the money too simple-minded and demands that her son at least come up with a conspiracy. Negotiations break down."},"E328.2":{"s":"Taren chooses a hike where the truth can be told without family scandals. He joins the party.","f":"Taren refuses to join the new party until his mother stops looking for intrigue behind him. Can't hire him.","v":{"rs":"Taren is willing to join, but there is no room for him in your party. He rewards the offer of an escape with gold."}},"E328.3":{"s":"{{heroName}} convinces Ilzara to recognize direct conversation as a new form of family art. The matriarch pays in gold for Taren's peaceful departure.","f":"Ilzara denounces the negotiations as a dishonest attempt to circumvent tradition, and her guards clash."},"E328.4":{"s":"You leave Ilzara and Taren debating how much honesty their kind can bear. The son points out once again where the rest of the money is."},"E329.1":{"s":"You ask Fael a question, and the crystal answers before he can open his mouth, revealing a golden cache at the table.","f":"The stone utters a forbidden phrase and inflicts {{affectedHeroName}} a serious wound.","v":{"nf":"The crystal flares on the premature response, but no eligible combatants are gravely wounded. The interrogation is interrupted."}},"E329.2":{"s":"You pay the interrogator for information and leave without waiting for the next predicted answer. The stone whispers something after him."},"E329.3":{"s":"{{heroName}} discovers that the crystal does not repeat a lie but predicts the intention to tell one. The interrogator rewards the insight with gold and provisions.","f":"The stone turns towards the researcher with a sharp blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The crystal disrupts the research with a dangerous flash, but none of the eligible fighters are gravely wounded. Its structure remains a mystery."}},"E329.4":{"s":"You end a conversation in which the subject speaks before the other person. For the first time, Fael looks grateful for the silence."},"E330.1":{"s":"You guide both spiders across the bridge without letting their legs touch each other. Rellis and Saar give thanks in gold for saving the wedding.","f":"The spiders collide in the middle of the bridge, and their owners call their assistants to fight. A skirmish begins."},"E330.2":{"s":"You give the newlyweds the supplies and leave them to find a way to carry out the ceremony. The priestess thanks in gold for her support."},"E330.3":{"s":"{{heroName}} calms the spiders and sees them off one after another, without requiring the animals to form a wedding formation. The priestess rewards with gold.","f":"One of the spiders suddenly rushes across the bridge, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The spiders disrupt the procession, but none of the eligible fighters are gravely wounded. The wedding is delayed."}},"E330.4":{"s":"You leave Rellis and Saar in front of two motionless spiders. The priestess already suggests holding the wedding on both sides of the bridge."},"E331.1":{"s":"You pay for a place almost at the forge and pass by indignant miners. Bela puts your name on the list, no questions asked."},"E331.2":{"s":"You persuade the smiths' queue to stop trading in other people's time. The enterprising dwarf refunds some of the gold, and your party receives its share.","f":"Miners find trading convenient in some places and do not want to give it up. Bela continues to get angry at the cash register."},"E331.3":{"s":"{{heroName}} negotiates with Gorm on the priority of urgent field repairs. The master returns the gold for the vacated space.","f":"{{heroName}} cannot convince Gorm to let the party through without additional payment, and they charge gold for negotiations."},"E331.4":{"s":"You pass by a blacksmith's shop where they trade in anticipation. On the road they are already offering a place in the queue to the queue seller himself."},"E332.1":{"s":"You haul the lift cage to the upper level, and three miners reward their rescuers with gold. Thrum finally stops blaming the brakes.","f":"The rope jerks sharply, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The cage twitches dangerously, but none of the eligible combatants are gravely wounded. The miners remain between levels."}},"E332.2":{"s":"You pay Thrum for the miner's supplies and leave without waiting for the elevator to resume operation. Below they already name the price of the excursion."},"E332.3":{"s":"{{heroName}} finds the jammed brake pawl and returns the cage to motion. Grateful miners pay in gold.","f":"The lifting mechanism is sharply compressed and seriously injures {{affectedHeroName}}.","v":{"nf":"The mechanism fails repairs, but none of the eligible fighters are gravely wounded. The cage remains motionless."}},"E332.4":{"s":"You leave Thrum with a lift that defies the laws of mechanics. From the shaft comes another demand for breakfast."},"E333.1":{"s":"You convince the board that fine beer need not cause suffering. Hold rewards the defence of his recipe with gold.","f":"Tasters refuse to recognize the drink as worthy of tradition because no one winced. The trial continues."},"E333.2":{"s":"You buy travel provisions from Hold while the council decides the fate of his beer. The brewer is happy to have at least one transaction without tasting."},"E333.3":{"s":"{{heroName}} questions the workers and finds out that the recipe has long been improved together, without trying to deceive tradition. Hold pays gold for the testimony.","f":"Workers are afraid to quarrel with the board and do not testify about the recipe. {{heroName}} returns empty-handed."},"E333.4":{"s":"You leave it to the dwarves to suffer from delicious beer. The judge waits carefully for at least one visitor to wince."},"E334.1":{"s":"You offer the safe a courteous apology on Farn's behalf, and the lock finally clicks open. The treasurer rewards you with gold for saving the cashbox.","f":"The safe responds with a new message, “NOT SINCERELY ENOUGH,” and remains closed."},"E334.2":{"s":"You pay Dorrie for the supplies and leave Farn to apologize to the safe. The keys are in the lock, as before."},"E334.3":{"s":"{{heroName}} dismantles the rune mechanism without touching the security seals and opens the city safe. Farn pays the gold.","f":"The offended lock snaps its metal shutter shut, gravely wounding {{affectedHeroName}}.","v":{"nf":"The lock slams shut, but none of the eligible fighters is gravely wounded. The safe still demands politeness."}},"E334.4":{"s":"You wish the safe a good day and leave. A short message appears on its lock plate: “SAME TO YOU.”"},"E335.1":{"s":"You wait for Keda to deliver the final blow to the nail. Ault pays gold for your patient judging.","f":"The competition drags on into the night, and the blacksmiths are not even close to finishing. There are no rewards for spectators."},"E335.2":{"s":"You buy supplies from spectators while they watch a single nail for hours. No one takes their eyes off the hammer."},"E335.3":{"s":"{{heroName}} notices that Brun improves the structure of the metal with every rare blow. Judge Ault pays in gold for the technical report.","f":"{{heroName}} can't tell the difference between two nearly identical nails. The competition continues."},"E335.4":{"s":"You leave before the nine-hour nail is declared a sacred relic. The crowd freezes at the prospect of the next blow."},"E336.1":{"s":"You follow Kern's marks and find a mountain where the map showed an empty steppe. Found ore brings gold.","f":"Instead of an ore vein, travelers find a fortified encampment of armed strangers. The battle begins."},"E336.2":{"s":"You buy a genuine heavy ore sample from Kern without trying to find the missing mountain. Miri weighs it again."},"E336.3":{"s":"{{heroName}} traces the first landmarks and finds a hidden cache of ore with gold and supplies.","f":"On an unmarked slope, {{affectedHeroName}} is gravely wounded by a rockfall.","v":{"nf":"The unknown slope crumbles, but none of the eligible fighters are gravely wounded. The route has to be interrupted."}},"E336.4":{"s":"You're not looking for a mountain that refuses to be on the map. Kern puts the sample in his bag and studies the empty steppe again."},"E337.1":{"s":"You buy supplies from Kezz, after carefully listening to all their shortcomings. The demon is surprised to give out the goods without a single hidden condition."},"E337.2":{"s":"You help Kezz explain to customers that fair warning is not a new trap. The demon pays gold for the saved trade.","f":"Clients mistake your participation for advertising and demand a refund for suspicious advice. The party loses gold."},"E337.3":{"s":"{{heroName}} checks the transactions and confirms: Kezz really tells the truth about each product. The grateful demon pays in gold.","f":"{{heroName}} finds that the warnings are too vague for full approval. The transactions remain suspect."},"E337.4":{"s":"You thank Kezz for the honest day and leave without purchasing anything. The demon looks longingly at the goods that he could not sell."},"E338.1":{"s":"You find the holder of ticket 666 in the last row, and the queue finally moves. Nak rewards you with gold for ending the delay.","f":"The owner of the coupon calls for assistants, fearing immediate payment for the room. A skirmish begins."},"E338.2":{"s":"You pay Nak to pass the stuck line. The demons remain silent when number 666 is announced."},"E338.3":{"s":"{{heroName}} checks the issued tickets and spots the demon hiding his number under his clothes. Nak gives you gold in thanks.","f":"{{heroName}} finds out that the coupon was resold several times, and the trace of the owner is lost. The queue doesn't move."},"E338.4":{"s":"You go around the black arch. From a distance the receptionist’s voice can still be heard: “Number six hundred sixty-six!”"},"E339.1":{"s":"You help Rakh keep the lanterns alight until dawn, calming the crimson flames. The charcoal-burner rewards you with gold.","f":"At night, armed creatures emerge from the darkness, reaching for the frightened fire. A skirmish begins."},"E339.2":{"s":"You give Rakh provisions for the night march, and he rewards you with gold for helping his frightened flame."},"E339.3":{"s":"{{heroName}} discovers that the flame fears the strange cold radiating through the darkness, not the night itself. Rakh rewards the discovery with gold.","f":"An attempt to test the properties of fire turns into a flash, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The flames erupt dangerously, but no eligible combatants are gravely wounded. The cause of the fear remains unknown."}},"E339.4":{"s":"You don't find out what the demonic flame is afraid of. Rakh again raises the lantern higher so that it does not disappear."},"E340.1":{"s":"You declare the beginning of the minute to be a witness, and the hourglass finally turns over. Azrel pays in gold for the countdown.","f":"The demon declares the decision a violation of the terms and calls for armed intermediaries. A skirmish begins."},"E340.2":{"s":"You give Azrel the gold for freeing Lorne from a minute that never began. The sand in the clock finally settles."},"E340.3":{"s":"{{heroName}} finds the legal limit of the bargain: without a starting point, the agreed minute has never begun. Azrel refunds the gold for the cancelled contract.","f":"{{heroName}} cannot convince the parties, and Azrel recovers the gold for the judicial review. The clock is still standing."},"E340.4":{"s":"You leave Lorne and Azrel arguing about the minute that lasts the fifth hour. The sand still doesn't fall."},"E341.1":{"s":"You help Tik collect three sincere apologies, free of seals or oaths. The demon rewards the restoration of his dignity with gold.","f":"Tick rejects each apology as not sincere enough and continues to make a list of debtors."},"E341.2":{"s":"You buy provisions from the innkeeper while Tik parades his list of grievances. She asks him not to occupy her chair."},"E341.3":{"s":"{{heroName}} explains to the debtors what Tick is really waiting for and leads them to a simple conversation. The demon pays in gold for mediation.","f":"One of the debtors considers Tick's demands extortion and calls his friends. A skirmish begins."},"E341.4":{"s":"You apologize to Tick in advance for anything you could have done and leave. The demon spends a long time looking for a suitable entry in the list."},"E342.1":{"s":"You find a clerical error swapping districts 18 and 81 and force the gatekeeper to move the infernal doorway to its proper address. Malen rewards you with gold.","f":"The demon refuses to leave the approved address and calls armed portal guards. The battle begins."},"E342.2":{"s":"You buy travel food from Zora before the portal's heat ruins the rest. The cook promptly shuts the storeroom."},"E342.3":{"s":"{{heroName}} removes the erroneously installed frame and closes the opening. Malen pays in gold for the returned storage room.","f":"The portal frame is hit with hot energy, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The fire frame disrupts the dismantling, but none of the eligible fighters are gravely wounded. The cheese continues to melt."}},"E342.4":{"s":"You decide to have dinner elsewhere while Malen proves to the demon the difference between 18 and 81. Zora tries to save the last piece of cheese."},"E343.1":{"s":"You convince Liel to replace the overdue rain with help for the starving peasants. The angel gives out supplies, and Tom smiles for the first time.","f":"The angel cannot change the address of an already prepared miracle and remains standing over an empty field. The village receives no help."},"E343.2":{"s":"You leave some food for the starving villagers. Tom rewards your help with gold, without a promise of miracles."},"E343.3":{"s":"{{heroName}} arranges for Liel to compensate the harvest with supplies and gold instead of rain. The village makes a decision.","f":"{{heroName}} does not find a way to turn the belated rain into a useful gift. The dispute with the angel remains open."},"E343.4":{"s":"You leave Liel and Tom in front of an empty barn. The angel still offers rain, which no one asks for anymore."},"E344.1":{"s":"You hold the heated halo steady while Sero works out the dent. Faril rewards the repair with gold.","f":"The rim slips out of its holders and {{affectedHeroName}} is severely injured.","v":{"nf":"The halo breaks when heated, but none of the eligible fighters are gravely wounded. Repairs have to be stopped."}},"E344.2":{"s":"You buy provisions from the pilgrims and leave Faril proving his angelic nature without a halo. Sero heats the ring again."},"E344.3":{"s":"{{heroName}} holds the shining rim on supports, and Sero finally straightens its shape. The angel thanks with gold.","f":"The hot halo breaks out of the mount and causes {{affectedHeroName}} a serious injury.","v":{"nf":"The rim is torn off its supports, but none of the eligible combatants are gravely wounded. Faril is left without a halo."}},"E344.4":{"s":"You leave Sero to repair the celestial equipment. Faril talks indignantly about the second paid entrance to his own temple."},"E345.1":{"s":"You support Iara: crime does not arise from one possible intention. The judge thanks in gold for a clear decision.","f":"Vel refuses to accept the excuse and demands a new trial of his own thoughts. The investigation is ongoing."},"E345.2":{"s":"You give supplies to the neighbour Vel never harmed. He rewards your kindness with gold, while Vel is advised to begin with an apology."},"E345.3":{"s":"{{heroName}} helps Vel distinguish guilt for a thought from responsibility for an act. The judge rewards the conversation with gold.","f":"Vel continues to demand punishment for the unfulfilled plan, despite the explanations. The dispute is not resolved."},"E345.4":{"s":"You leave Jaru to deal with the case of a man who blames himself for something he didn't do. Vel again asks about the right to punishment."},"E346.1":{"s":"You discover that the bell is responding to a hidden crack in its own seal, not to the pilgrims. Ciel thanks you for the solution and gives you gold.","f":"Pilgrims consider the investigation an accusation of lies and are calling for armed defenders. A skirmish begins."},"E346.2":{"s":"You leave supplies to repair the shrine's cracked bell. Ciel rewards the help with gold."},"E346.3":{"s":"{{heroName}} reveals an erroneous bell setting that caused it to ring for any voice. Ciel rewards with gold.","f":"The damaged seal responds with a sharp ringing sound, causing {{affectedHeroName}} a serious injury.","v":{"nf":"The bell rings with dangerous force, but none of the eligible fighters is gravely wounded. Its testimony remains unreliable."}},"E346.4":{"s":"You don't test the party's integrity on a faulty bell. Ciel covers the crack with a cloth and stops receiving pilgrims."},"E347.1":{"s":"You hide Iaral in a barn and meet the hunters before they can unfurl their nets. The angel thanks with gold for protection.","f":"The hunters find the barn and call for reinforcements. The battle begins."},"E347.2":{"s":"You give Iaral the supplies and show him the hidden path from the barn. The angel thanks with gold for the opportunity to escape persecution."},"E347.3":{"s":"{{heroName}} intercepts the hunters at the fork, preventing them from reaching the barn. Iaral thanks with gold.","f":"In a hidden ambush, {{affectedHeroName}} is gravely wounded by a trapping net.","v":{"nf":"The hunters thwart your interception, but none of the eligible fighters is gravely wounded. The barn remains in danger."}},"E347.4":{"s":"You leave without interfering with the hunt for the wounded angel. Nemi closes the barn door behind Iaral."},"E348.1":{"s":"You prove that the modern road has a more recent right of way than the ancient map of the sky. The caravan pays you gold for reopening the passage.","f":"ES does not recognize any ground amendments to the air route. The cloud remains on the road."},"E348.2":{"s":"You pay Es for temporary passage through his low cloud. The caravan men bow their heads indignantly as they pass under the heavenly controller."},"E348.3":{"s":"{{heroName}} compares the date the road was built with the old sky chart and finds a jurisdictional error. Es rewards the settlement with gold.","f":"{{heroName}} does not find any official cancellation of the old air route. They charge gold for checking, but the cloud doesn’t go away."},"E348.4":{"s":"You walk around a low cloud along the side of the road. Es is still demanding that the carts be removed from the three-hundred-year-old sky area."},"E349.1":{"s":"You sort the coins into piles so the dragon's tail can keep track, and Khar finally finishes the register. The merchants reward you with gold.","f":"The young dragon sneezes again at the most inopportune moment. Nobody wants to count thousands of coins again."},"E349.2":{"s":"You buy provisions from merchants waiting for their deposits back. Khar starts counting again from the very first coin."},"E349.3":{"s":"{{heroName}} organizes separate boxes for each coin category, leaving no room for confusion. Merchants give thanks in gold.","f":"{{heroName}} cannot get the dragon to stop moving coins, and the treasury loses gold for a failed check."},"E349.4":{"s":"You leave until the next dragon sneeze. Khar is already pronouncing the number nine thousand and ninety-nine."},"E350.1":{"s":"You ask the egg what prevents it from being born, and you finally get a meaningful answer. Raash thanks you for the conversation and gives you supplies.","f":"The shell pushes the approaching one sharply, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The egg shakes dangerously, but none of the eligible fighters are gravely wounded. You don't get an answer to the question."}},"E350.2":{"s":"You leave supplies for the keepers so they don't rush the hatching. Raash pays gold for his patience."},"E350.3":{"s":"{{heroName}} discovers that the hatchling is healthy but the enchanted shell is not yet ready to crack. Raash rewards the diagnosis with gold.","f":"The protective shell gives a magical boost, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The shell repels explorers, but no eligible combatants are gravely wounded. The reason for the delay has not been established."}},"E350.4":{"s":"You leave Raash to wait for agreement from inside the huge egg. As a farewell, a firm “later” comes from there."},"E351.1":{"s":"You follow the trail of the cloak to an abandoned post and find gold there left by the provocateur. Varrash doubts the scales for the first time.","f":"The trail leads to an armed ambush by the person who planted the evidence. A skirmish begins."},"E351.2":{"s":"You give the outpost supplies for the wounded messenger, and the officer pays in gold for timely assistance."},"E351.3":{"s":"{{heroName}} compares the messenger’s testimony with the coat of arms and finds out who wanted to quarrel between the two houses. The ambassador thanks with gold for the conflict averted.","f":"{{heroName}} does not find who would benefit from leaving such obvious evidence. Varrash still demands an investigation into the intrusion."},"E351.4":{"s":"You don't get into a Draconid dispute over red scales. The wounded messenger again repeats the story of the man in the cloak."},"E352.1":{"s":"You listen to Marak's chronicle without skipping a single ending. The old dragon rewards you with gold for several hours of genuine attention.","f":"Marak stops reading after the first missing line and demands Saara's return. There will be no reward."},"E352.2":{"s":"You buy supplies from Saara before she leaves. The librarian hastily marks the page where Marak left off."},"E352.3":{"s":"{{heroName}} not only reads the chronicle, but discusses with Marak old events that he personally remembers. The dragon thanks with gold and supplies.","f":"Marak catches {{heroName}} using the wrong name on the timeline and ends the discussion. You have to read the page again."},"E352.4":{"s":"You wish the old dragon an attentive reader. Marak grumbles that a good listener should not swallow endings."},"E353.1":{"s":"You convince Rush and Kev to make the exit and storage room common, and use chalk to mark only private corners. Illa thanks with gold.","f":"Two dragons cannot even share the smoke from the fire and call for the protection of their halves. A skirmish begins."},"E353.2":{"s":"You give Illa supplies for another day of negotiations, and she pays in gold for the opportunity not to carry food over the line."},"E353.3":{"s":"{{heroName}} establishes passage rights through the left half of the cave and access to the storeroom on the right. Both dragons agree, and Illa rewards you with gold.","f":"{{heroName}} cannot agree on the right to an echo that can be heard throughout the cave. They demand gold for a retrial."},"E353.4":{"s":"You leave Rush and Kev to argue over who owns the smoke. Illa sits at the chalk line with a tray of food."},"E354.1":{"s":"You walk beside Kesh along the suspension bridge, matching his careful pace. The courier delivers his reports and rewards you with gold.","f":"In the middle of the crossing, {{affectedHeroName}} is gravely wounded from a broken fastening.","v":{"nf":"The bridge sways dangerously, but none of the eligible combatants are gravely wounded. Kesh returns to shore."}},"E354.2":{"s":"You give Kesh the supplies for the long detour, and the courier thanks you in gold for the opportunity not to cross the bridge."},"E354.3":{"s":"{{heroName}} teaches Kesh to focus on the far bank rather than the drop below and guides him across. Raana rewards you with gold.","f":"With a sharp gust of wind, {{affectedHeroName}} is gravely wounded.","v":{"nf":"The crossing is disrupted due to the wind, but none of the eligible fighters are gravely wounded. The reports remain on the same bank."}},"E354.4":{"s":"You leave Kesh before the bridge he fears to cross. The courier quietly tucks his reports deeper into his bag."},"E355.1":{"s":"You check Ruk's papers and return the sheep to its rightful shepherd. The beastman rewards you with supplies, while Bens scowls at the documents.","f":"Bens refuses to give up the sheep even after checking the documents. The dispute remains in place."},"E355.2":{"s":"You pay Ruk for the sheep and leave it with Bens without trampling the former owner's rights. The farmer shares provisions in thanks."},"E355.3":{"s":"{{heroName}} confirms Ruk's right to the flock and offers to arrange the sheep's transfer to Bens separately. The careful ruling earns your party gold.","f":"{{heroName}} discovers a discrepancy in the old drawing of the lamb, and the argument returns to square one. Gold coins are used for verification."},"E355.4":{"s":"You leave a sheep between two shepherds. She finally chews through the rope, as if deciding to exercise her own right to choose."},"E356.1":{"s":"You find a hidden passage behind a stacked woodpile and enter the inn. Mira thanks you for the lucky guess and gives you supplies.","f":"A search of all the walls yields nothing, and the carpenter Bars just shrugs from the roof. There is no dinner."},"E356.2":{"s":"You pay Mira for the hint and go through an entrance invisible from the road. The fox gives out supplies along with a hot dinner."},"E356.3":{"s":"{{heroName}} notices the cook carrying trays through the hatch under the canopy. The party gets inside and receives supplies.","f":"{{heroName}} sees only empty windows through which the plates disappear. The entrance cannot be found."},"E356.4":{"s":"You choose a tavern with ordinary doors and leave Mira to be entertained by a new circle of guests. The leopard on the roof nods approvingly."},"E357.1":{"s":"You convince Bram to allow the Fox to take only a few leaves without destroying the flower on his brother's grave. The herbalist thanks with gold.","f":"Bram does not believe that the plant will survive the cutting, and remains at his post near the only flower. There is no cure."},"E357.2":{"s":"You give the Fox supplies to search for another remedy, and she thanks you with gold for the time it will give the patient."},"E357.3":{"s":"{{heroName}} finds a way to take the medicinal part of the root without killing the flower. Bram agrees, and Lisa pays in gold.","f":"Bram mistakes the attempt to take the flower for an attack and gravely wounds {{affectedHeroName}}.","v":{"nf":"Bram stops the attempt to harvest the plant, but none of the eligible fighters is gravely wounded. The flower stays on the grave."}},"E357.4":{"s":"You leave Bram to guard the flower on the grave. The fox asks again whether it is possible to save the patient without taking away someone else’s memory."},"E358.1":{"s":"You help Sher reach a safe house before Mole can take another wager. Doctor Puma rewards you with gold.","f":"Sher gets into another argument along the way and refuses to be accompanied. The last life remains on his conscience."},"E358.2":{"s":"You give Puma supplies to treat Sher, and she thanks you with gold for your help instead of new bets."},"E358.3":{"s":"{{heroName}} accompanies Sher to the doctor, distracting him from bookmakers and dubious duels. Puma thanks with gold.","f":"On the way to the doctor, {{affectedHeroName}} is gravely wounded while protecting Sher from further trouble.","v":{"nf":"Sher rushes into another dangerous adventure, but none of the eligible fighters is gravely wounded. The escort ends."}},"E358.4":{"s":"You refuse to bet on Sher's last life. Mole closes the book indignantly, and Puma finally smiles."},"E359.1":{"s":"You uphold the old IOU and persuade Dil to begin paying the family's inherited debt. Omar rewards the ruling with gold.","f":"Dil denies the seventy-two-year claim and asks for a new trial. There is no agreement."},"E359.2":{"s":"You pay part of Dil's debt, and Omar marks the old receipt. The merchant thanks you, though the argument over inheriting debt continues."},"E359.3":{"s":"{{heroName}} checks the signature, seals and conditions for transferring the debt to the family. Dil accepts the conclusion, Omar pays in gold for the examination.","f":"{{heroName}} discovers the disputed word in the burnt part of the receipt, and the parties demand reimbursement of expenses. The treasury is losing gold."},"E359.4":{"s":"You leave Omar with a receipt that outlives the debtor, and Dil with a family dispute. The old debt is still not repaid."},"E360.1":{"s":"You wait for Thorne to finish reading the last paragraph, and Owl shares the supplies for his patience. The bear closes the book with a heavy sigh.","f":"Thorne discovers that the novel continues with a second volume and refuses to vacate the library. The party does not get enough supplies."},"E360.2":{"s":"You buy supplies from waiting readers while a dramatic reading is heard from the library. Thorne turns another page."},"E360.3":{"s":"{{heroName}} asks Owl exactly how many pages remain and helps organise a queue for the books everyone needs. The grateful readers reward you with gold.","f":"{{heroName}} finds out that Thorne has started rereading his favorite chapter. It is not possible to predict the opening time."},"E360.4":{"s":"You leave to look for cards in another library. From behind the closed door an angry voice is heard: “Don’t open it!”"}});
export { OUTCOMES_EN_E291_E360 };
